import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { startFrame: number; endFrame?: number; word?: string; text?: string; index?: number; wordIndex?: number };
type ShotProps = { wordCues?: WordCue[] };

const P = { field: '#F3F1EB', ivory: '#FFFCF4', white: '#FFFFFF', ink: '#142536', slate: '#627383', teal: '#087F79', coral: '#ED705F', rule: '#D5DDD9' };
const FONT = 'Inter, Arial, sans-serif';
const TIGHT = 'Inter Tight, Inter, Arial, sans-serif';
const MONO = 'IBM Plex Mono, monospace';
const STARTS = [10, 66, 77, 109, 121, 132, 147, 157, 163, 180, 186, 205, 214, 228, 238, 256, 309, 340, 364, 382, 397, 428];
const ENDS = [50, 78, 113, 125, 135, 151, 159, 167, 183, 189, 209, 218, 231, 242, 259, 287, 336, 368, 383, 396, 432, 456];
const cap = (n: number) => Math.max(0, Math.min(1, n));
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const ease = Easing.bezier(0.22, 0.75, 0.22, 1);
const smooth = (f: number, a: number, b: number) => interpolate(f, [a, Math.max(a + 1, b)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
const linear = (f: number, a: number, b: number) => interpolate(f, [a, Math.max(a + 1, b)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
const TILE = 'M -65 -86 H 38 L 65 -59 V 86 H -65 Z';
const CORNER = 'M 38 -86 L 65 -59 H 38 Z';
const MARK = 'M -23 4 L -6 21 L 27 -19';

const FlightEcho: React.FC<{ x: number; y: number; scale: number; opacity: number; rotation?: number }> = ({ x, y, scale, opacity, rotation = 0 }) => (
  <g transform={'translate(' + x + ' ' + y + ') rotate(' + rotation + ') scale(' + scale + ')'} opacity={opacity}>
    <path d={TILE} fill={P.ivory} fillOpacity={0.14} stroke={P.ink} strokeOpacity={0.55} strokeWidth={1.25} />
  </g>
);

const VoteTile: React.FC<{ x: number; y: number; scale: number; rotation?: number; opacity?: number; recorded?: number }> = ({ x, y, scale, rotation = 0, opacity = 1, recorded = 0 }) => (
  <g transform={'translate(' + x + ' ' + y + ') rotate(' + rotation + ') scale(' + scale + ')'} opacity={opacity}>
    <path d={TILE} fill={P.ivory} stroke='#D8DDD5' strokeWidth={1.5} filter='url(#s01TileShadow)' />
    <path d={CORNER} fill={P.coral} />
    <path d={MARK} fill='none' stroke={P.ink} strokeWidth={10} strokeLinecap='square' strokeLinejoin='miter' />
    <path d={TILE} fill='none' stroke={P.teal} strokeWidth={3} opacity={recorded} />
  </g>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const themeMode = 'light' as const;
  const start = (i: number) => {
    const cue = cues.find((c) => c.wordIndex === i || c.index === i) || cues[i];
    return cue && Number.isFinite(cue.startFrame) ? cue.startFrame : STARTS[i];
  };
  const end = (i: number) => {
    const cue = cues.find((c) => c.wordIndex === i || c.index === i) || cues[i];
    return cue && Number.isFinite(cue.endFrame) ? Number(cue.endFrame) : start(i) + ENDS[i] - STARTS[i];
  };
  const last = Math.max(1, durationInFrames - 1);
  const f = Math.min(frame, last);
  const drift = smooth(f, end(21) + 1, last);
  const sceneFit = Math.min(width / 1920, height / 1080);
  const cameraKey = [0, end(0), end(2), start(5), end(10), start(12), end(15), start(17), end(19), start(20), end(21), last];
  const camera = (values: number[]) => interpolate(f, cameraKey, values, { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: Easing.inOut(Easing.cubic) });
  const zoom = camera([1.5, 1.3, 1.05, 1.05, 1.12, 1.12, 1.08, 1.08, 1.2, 1.2, 1.02, 1.04]);
  const travel = linear(f, start(17), end(19));
  const trackX = mix(60, 138, travel);
  const trackY = mix(7, -6, travel);
  const panX = f >= start(17) && f <= end(19) ? trackX : camera([-260, -195, -15, -15, -88, -88, 45, 60, 138, 138, 27, 44]);
  const panY = f >= start(17) && f <= end(19) ? trackY : camera([40, 24, 0, 0, 10, 10, 8, 7, -6, -6, 1, 0]);
  const arrival = spring({ frame: Math.max(0, f - start(0)), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const boxLift = 36 * (1 - arrival);
  const boxOpacity = mix(0.24, 1, smooth(f, start(0), start(0) + 20));
  const dissolve = smooth(f, start(12), end(15));
  const assembly = smooth(f, start(14), end(15) + 22);
  const railOpacity = smooth(f, start(14), start(15) + 18);
  const heroX = mix(742, 1385, travel);
  const heroY = f < start(17) ? mix(261, 413, smooth(f, start(12), end(15))) : mix(413, 460, travel) - Math.sin(travel * Math.PI) * 17;
  const heroScale = mix(1.04, 0.9, travel);
  const heroRotation = mix(-6, 0, smooth(f, start(12), end(15)));
  const record = smooth(f, start(21), end(21));
  const focusRaw = spring({ frame: Math.max(0, f - start(20)), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const focusScale = 0.9 + focusRaw * 0.1;
  const focusOpacity = f >= start(20) ? smooth(f, start(20), start(20) + 10) : 0;
  const seamProgress = smooth(f, start(20), end(21));
  const slots = [553, 761, 969, 1177, 1385];
  const queue = [
    { x: 275, y: 472, scale: 0.71, rotation: -7 },
    { x: 365, y: 452, scale: 0.75, rotation: -6 },
    { x: 455, y: 430, scale: 0.8, rotation: -5 },
    { x: 548, y: 406, scale: 0.85, rotation: -4 },
    { x: 642, y: 382, scale: 0.9, rotation: -3 }
  ];

  const plane = (targetX: number, targetY: number, sourceX: number, sourceY: number, turn: number, finalSX: number, finalSY: number, delay: number) => {
    const p = smooth(f, start(12) + delay, end(15) + delay);
    const burst = Math.sin(p * Math.PI);
    const x = mix(sourceX, targetX, p) + burst * 13;
    const y = mix(sourceY + boxLift, targetY, p) - burst * 45;
    return 'translate(' + x + ' ' + y + ') rotate(' + (turn * burst) + ') scale(' + mix(1, finalSX, p) + ' ' + mix(1, finalSY, p) + ') translate(' + (-sourceX) + ' ' + (-sourceY) + ')';
  };

  const supportingTiles = [0, 1, 2, 3].map((i) => {
    const original = queue[i];
    const compact = smooth(f, start(5) + i * 5, end(10));
    const compactX = mix(original.x, 543 + i * 39, compact);
    const compactY = mix(original.y, 437 - i * 5, compact);
    const release = smooth(f, start(12) + i * 5, end(15) + i * 5);
    const anchorAt = start(21) + i * 5;
    const anchor = smooth(f, anchorAt, anchorAt + 12);
    const approach = linear(f, start(17) + i * 5, start(20) + i * 5);
    const parkedX = 392 + i * 166;
    const hoverX = mix(compactX, parkedX, release);
    const hoverY = mix(compactY, 379 - i * 9, release);
    const x = mix(mix(hoverX, slots[i], approach), slots[i], anchor);
    const y = mix(mix(hoverY, 416, approach), 460, anchor);
    const scale = mix(mix(original.scale, 0.7, release), 0.76, anchor);
    const rotation = mix(original.rotation, 0, Math.max(release, approach));
    const visible = smooth(f, end(0) + i * 5, end(0) + 18 + i * 5);
    const echoActivity = smooth(f, start(17) + i * 5, start(17) + 16 + i * 5) * (1 - anchor);
    return { i, x, y, scale, rotation, visible, anchor, echoActivity };
  });

  return (
    <AbsoluteFill style={{ background: P.field, overflow: 'hidden', fontFamily: FONT, color: P.ink }}>
      <AbsoluteFill style={{ background: 'linear-gradient(155deg, #FFFEFA 0%, #F3F1EB 42%, #E8EDE7 75%, #F7F4EC 100%)' }} />
      <AbsoluteFill style={{ background: 'radial-gradient(68% 83% at ' + (67 + drift * 3) + '% 22%, rgba(255,255,255,0.96) 0%, rgba(255,255,255,0.5) 36%, rgba(255,255,255,0) 73%)' }} />
      <AbsoluteFill style={{ background: 'radial-gradient(48% 42% at 27% 75%, rgba(197,211,207,0.24) 0%, transparent 75%)', transform: 'translateX(' + (12 * Math.sin(f / 180)) + 'px)' }} />
      <AbsoluteFill style={{ opacity: 0.24 }}><mg.GridBackground mode={themeMode} gridSize={48} /></AbsoluteFill>
      <div style={{ position: 'absolute', width: 1920, height: 1080, left: (width - 1920 * sceneFit) / 2, top: (height - 1080 * sceneFit) / 2, transform: 'scale(' + sceneFit + ')', transformOrigin: '0 0' }}>
        <div style={{ position: 'absolute', left: 86, top: 219, width: 1748, height: 794, borderTop: '1px solid rgba(98,115,131,0.12)', borderBottom: '1px solid rgba(98,115,131,0.12)', pointerEvents: 'none' }} />
        <div style={{ position: 'absolute', inset: 0, opacity: 0.45, pointerEvents: 'none' }}>
          <mg.Marker x={90} y={228} variant='cross' color={P.slate} />
          <mg.Marker x={1830} y={228} variant='cross' color={P.slate} />
          <mg.Marker x={90} y={1012} variant='cross' color={P.slate} />
          <mg.Marker x={1830} y={1012} variant='cross' color={P.slate} />
        </div>

        <div style={{ position: 'absolute', left: 90, top: 180, width: 1740, height: 860 }}>
          <mg.CameraRig zoom={zoom} x={panX} y={panY}>
            <div style={{ position: 'absolute', width: 1740, height: 860, inset: 0, transformOrigin: '870px 430px' }}>
              <div style={{ position: 'absolute', left: 150 + dissolve * 215, top: 528 + dissolve * 55, width: mix(780, 1210, dissolve), height: mix(158, 86, dissolve), borderRadius: '50%', background: 'radial-gradient(ellipse, rgba(20,37,54,0.12) 0%, rgba(20,37,54,0.045) 44%, transparent 73%)', filter: 'blur(19px)', opacity: mix(0.85, 0.48, dissolve) }} />
              <svg width={1740} height={860} viewBox='0 0 1740 860' style={{ position: 'absolute', inset: 0, overflow: 'visible' }}>
                <defs>
                  <linearGradient id='s01Front' x1='0' y1='0' x2='0.9' y2='1'>
                    <stop offset='0%' stopColor='#FFFFFF' /><stop offset='62%' stopColor='#F4F2E9' /><stop offset='100%' stopColor='#E5E8DE' />
                  </linearGradient>
                  <linearGradient id='s01Side' x1='0' y1='0' x2='1' y2='1'>
                    <stop offset='0%' stopColor='#E4E9E0' /><stop offset='100%' stopColor='#C7D4CE' />
                  </linearGradient>
                  <linearGradient id='s01Top' x1='0' y1='0' x2='0' y2='1'>
                    <stop offset='0%' stopColor='#FFFFFF' /><stop offset='100%' stopColor='#ECEFE6' />
                  </linearGradient>
                  <linearGradient id='s01Rail' x1='0' y1='0' x2='0' y2='1'>
                    <stop offset='0%' stopColor='#FFFFFF' stopOpacity='0.96' /><stop offset='100%' stopColor='#E7EBE3' stopOpacity='0.96' />
                  </linearGradient>
                  <filter id='s01TileShadow' x='-80%' y='-55%' width='260%' height='250%'>
                    <feDropShadow dx='0' dy='12' stdDeviation='10' floodColor='#142536' floodOpacity='0.12' />
                    <feDropShadow dx='0' dy='2' stdDeviation='1.5' floodColor='#142536' floodOpacity='0.08' />
                  </filter>
                  <filter id='s01BoxShadow' x='-35%' y='-35%' width='180%' height='190%'>
                    <feDropShadow dx='0' dy='20' stdDeviation='17' floodColor='#142536' floodOpacity='0.105' />
                  </filter>
                  <filter id='s01SlotShadow' x='-45%' y='-35%' width='190%' height='190%'>
                    <feDropShadow dx='0' dy='7' stdDeviation='6' floodColor='#142536' floodOpacity='0.07' />
                  </filter>
                </defs>

                <g opacity={railOpacity}>
                  <rect x={451} y={553} width={Math.max(1, 1047 * assembly)} height={44} rx={18} fill='url(#s01Rail)' stroke={P.rule} strokeWidth={1.25} filter='url(#s01SlotShadow)' />
                  <path d='M 472 558 H 1478' fill='none' stroke='#FFFFFF' strokeWidth={2} opacity={assembly} />
                  {slots.map((x, i) => {
                    const slotEntry = smooth(f, start(15) + i * 5, end(15) + 19 + i * 5);
                    return (
                      <g key={'slot-' + i} opacity={slotEntry} transform={'translate(0 ' + (14 * (1 - slotEntry)) + ')'}>
                        <rect x={x - 81} y={350} width={162} height={222} rx={17} fill='#FFFFFF' fillOpacity={0.58} stroke={P.rule} strokeWidth={1.5} filter='url(#s01SlotShadow)' />
                        <rect x={x - 68} y={363} width={136} height={196} rx={11} fill='#EDF0E8' fillOpacity={0.55} />
                        <path d={'M ' + (x - 65) + ' 538 V 549 H ' + (x + 65) + ' V 538'} fill='none' stroke={P.ink} strokeOpacity={0.38} strokeWidth={2} />
                        <path d={'M ' + x + ' 572 V 582'} fill='none' stroke={P.ink} strokeWidth={2} strokeOpacity={0.45} />
                      </g>
                    );
                  })}
                  <path d='M 474 610 H 1494' fill='none' stroke={P.rule} strokeWidth={1} opacity={assembly * 0.6} />
                </g>

                {supportingTiles.map((tile) => (
                  <g key={'queue-' + tile.i}>
                    {[3, 2, 1].map((echo) => <FlightEcho key={echo} x={tile.x - echo * 21 * (1 - tile.anchor)} y={tile.y - echo * 2 * (1 - tile.anchor)} scale={tile.scale} rotation={tile.rotation} opacity={tile.visible * tile.echoActivity * (0.09 - echo * 0.019)} />)}
                    <VoteTile x={tile.x} y={tile.y} scale={tile.scale} rotation={tile.rotation} opacity={tile.visible} />
                  </g>
                ))}

                {(() => {
                  const q = queue[4];
                  const p = smooth(f, start(5) + 20, end(10));
                  const merge = smooth(f, start(12), start(14));
                  const fade = 1 - smooth(f, start(14), end(15));
                  return <VoteTile x={mix(mix(q.x, 690, p), 742, merge)} y={mix(q.y, 398, p)} scale={mix(q.scale, 0.69, merge)} rotation={mix(q.rotation, 0, merge)} opacity={smooth(f, end(0) + 20, end(0) + 38) * fade} />;
                })()}

                <g opacity={boxOpacity}>
                  <g transform={plane(922, 574, 712, 490, -5, 2.82, 0.065, 0)}>
                    <path d='M 470 350 H 955 V 610 H 470 Z' fill='url(#s01Front)' stroke='#CDD7CF' strokeWidth={1.5} filter='url(#s01BoxShadow)' />
                  </g>
                  <g transform={plane(1370, 570, 1022, 435, 11, 1.02, 0.037, 5)}>
                    <path d='M 955 350 L 1090 260 V 520 L 955 610 Z' fill='url(#s01Side)' stroke='#BACCC3' strokeWidth={1.5} />
                  </g>
                  <g transform={plane(966, 552, 780, 305, -8, 1.75, 0.105, 10)}>
                    <path d='M 470 350 L 605 260 H 1090 L 955 350 Z' fill='url(#s01Top)' stroke='#D7DFD6' strokeWidth={1.5} />
                  </g>
                  <g transform={plane(969, 582, 743, 307, -3, 3.71, 0.22, 6)}>
                    <path d='M 603 318 L 631 296 H 882 L 855 318 Z' fill={P.ink} />
                  </g>
                  <g transform={plane(966, 568, 713, 480, 6, 3.52, 0.035, 14)}>
                    <rect x={574} y={410} width={278} height={140} rx={5} fill='#E9EDE3' fillOpacity={0.64} stroke='#D9E0D5' strokeWidth={1.5} />
                  </g>
                  <g transform={plane(969, 587, 716, 578, -4, 3.66, 0.45, 10)}>
                    <path d='M 573 575 H 859 V 581 H 573 Z' fill={P.ink} />
                  </g>
                </g>

                {[3, 2, 1].map((echo) => {
                  const activity = smooth(f, start(17), start(17) + 10) * (1 - smooth(f, start(20), start(21)));
                  const distance = 23 * echo * (1 - smooth(f, start(20), start(21)));
                  return <FlightEcho key={'hero-echo-' + echo} x={heroX - distance} y={heroY - echo * 1.5} scale={heroScale} opacity={activity * (0.12 - echo * 0.025)} />;
                })}

                <g transform={'translate(' + heroX + ' ' + heroY + ') rotate(' + heroRotation + ') scale(' + heroScale + ')'}>
                  <path d={TILE + ' ' + CORNER} fill={P.ivory} stroke={P.coral} strokeWidth={2.6} strokeLinejoin='miter' filter='url(#s01TileShadow)' />
                  <path d={MARK} fill='none' stroke={P.ink} strokeWidth={10} strokeLinecap='square' strokeLinejoin='miter' />
                </g>
                <g transform={'translate(' + heroX + ' ' + heroY + ') rotate(' + heroRotation + ') scale(' + heroScale + ')'} opacity={record}>
                  <path d={TILE} fill='none' stroke={P.teal} strokeWidth={3.5} />
                  <path d={CORNER} fill={P.coral} />
                </g>

                <g opacity={focusOpacity}>
                  <path d='M 1342 552 H 1428' fill='none' stroke={P.ink} strokeWidth={3.5} strokeDasharray='86' strokeDashoffset={86 * (1 - seamProgress)} />
                  <path d='M 1385 596 V 625' fill='none' stroke={P.coral} strokeWidth={1.5} opacity={0.5 * record} />
                </g>
              </svg>

              <div style={{ position: 'absolute', left: 1285, top: 328, width: 200, height: 266, opacity: focusOpacity, transform: 'scale(' + focusScale + ')', transformOrigin: '50% 50%', pointerEvents: 'none' }}>
                <mg.FocusFrame color={P.coral} borderRadius={20} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%' }}>
                  <div style={{ width: 200, height: 266 }} />
                </mg.FocusFrame>
              </div>

              <div style={{ position: 'absolute', left: 473, top: 641, opacity: smooth(f, start(16), end(16)), transform: 'translateY(' + (10 * (1 - smooth(f, start(16), end(16)))) + 'px)', display: 'flex', alignItems: 'center', gap: 16 }}>
                <span style={{ display: 'block', width: 26, height: 1, background: P.slate, opacity: 0.6 }} />
                <span style={{ fontFamily: FONT, fontSize: 28, fontWeight: 500, letterSpacing: '0.07em', color: P.slate, whiteSpace: 'nowrap' }}>ILLUSTRATIVE RECORD MODEL</span>
              </div>
              <div style={{ position: 'absolute', left: 1292, top: 638, width: 186, height: 45, display: 'flex', alignItems: 'center', justifyContent: 'center', opacity: record, transform: 'translateY(' + (8 * (1 - record)) + 'px)', color: P.slate, fontFamily: MONO, fontWeight: 500, fontSize: 29, letterSpacing: '-0.03em' }}>recorded</div>
            </div>
          </mg.CameraRig>
        </div>

        <div style={{ position: 'absolute', left: 0, top: 0, width: 1920, height: 216, background: 'linear-gradient(180deg, rgba(250,249,244,0.99) 0%, rgba(250,249,244,0.96) 80%, rgba(250,249,244,0) 100%)', pointerEvents: 'none' }} />
        <mg.Heading kicker='THE PROMISE' title='Imagine an election' frameAt={2} style={{ position: 'absolute', left: 100, top: 70, maxWidth: 1100, fontFamily: TIGHT, fontWeight: 600, fontSize: 52, lineHeight: 1.08, color: P.ink }} />
        <div style={{ position: 'absolute', left: 100, top: 186, width: 72 * smooth(f, start(0), end(2)), height: 3, background: P.coral, opacity: 0.86 }} />
      </div>
      <AbsoluteFill style={{ pointerEvents: 'none', mixBlendMode: 'multiply' }}><mg.Noise opacity={0.04} /></AbsoluteFill>
    </AbsoluteFill>
  );
};

import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

const C = { paper: '#F3F1EB', white: '#FFFFFF', ink: '#142536', slate: '#627383', teal: '#087F79', coral: '#ED705F', rule: '#D5DDD9' };
const FONT = 'Inter, Arial, sans-serif';
const TIGHT = 'Inter Tight, Inter, Arial, sans-serif';
const MONO = 'IBM Plex Mono, monospace';
const NODES = [
  { x: 75, y: 335 },
  { x: 485, y: 180 },
  { x: 485, y: 490 },
  { x: 895, y: 180 },
  { x: 895, y: 490 },
  { x: 1305, y: 180 },
  { x: 1305, y: 490 }
];
const EDGES = [
  { a: 0, b: 1, bend: 0, phase: 0.00 },
  { a: 0, b: 2, bend: 0, phase: 0.29 },
  { a: 1, b: 3, bend: 0, phase: 0.16 },
  { a: 2, b: 4, bend: 0, phase: 0.43 },
  { a: 3, b: 5, bend: 0, phase: 0.27 },
  { a: 4, b: 6, bend: 0, phase: 0.63 },
  { a: 1, b: 4, bend: 0, phase: 0.37 },
  { a: 2, b: 3, bend: 0, phase: 0.71 },
  { a: 3, b: 6, bend: 0, phase: 0.51 },
  { a: 4, b: 5, bend: 0, phase: 0.84 },
  { a: 0, b: 3, bend: -120, phase: 0.22 },
  { a: 2, b: 6, bend: 155, phase: 0.58 }
];
const clamp = (v: number) => Math.min(1, Math.max(0, v));
const ease = Easing.bezier(0.22, 0.72, 0.22, 1);
const range = (f: number, a: number, b: number, from = 0, to = 1) => interpolate(f, [a, Math.max(a + 1, b)], [from, to], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
const curve = (edge: typeof EDGES[number]) => {
  const a = NODES[edge.a];
  const b = NODES[edge.b];
  const sx = a.x + 360;
  const sy = a.y + 80;
  const ex = b.x;
  const ey = b.y + 80;
  const reach = Math.max(32, (ex - sx) * 0.4);
  return { sx, sy, ex, ey, c1x: sx + reach, c1y: sy + edge.bend, c2x: ex - reach, c2y: ey + edge.bend };
};
const pointAt = (c: ReturnType<typeof curve>, t: number) => {
  const u = 1 - t;
  return { x: u * u * u * c.sx + 3 * u * u * t * c.c1x + 3 * u * t * t * c.c2x + t * t * t * c.ex, y: u * u * u * c.sy + 3 * u * u * t * c.c1y + 3 * u * t * t * c.c2y + t * t * t * c.ey };
};

const VoteTile: React.FC<{ checked?: boolean }> = ({ checked = true }) => (
  <div style={{ position: 'relative', width: 62, height: 76 }}>
    <div style={{ position: 'absolute', inset: 0, background: '#F8F5E9', borderRadius: 7, clipPath: 'polygon(0 0, 76% 0, 100% 19%, 100% 100%, 0 100%)', boxShadow: 'inset 0 0 0 1px #D9DDD3' }}>
      <div style={{ position: 'absolute', right: 0, top: 0, width: 15, height: 15, background: C.coral, clipPath: 'polygon(0 0, 100% 100%, 0 100%)' }} />
      <svg width="62" height="76" viewBox="0 0 62 76" style={{ position: 'absolute', inset: 0 }}>
        <path d="M17 36 L26 45 L44 24" fill="none" stroke={C.ink} strokeWidth="5" strokeLinecap="square" strokeLinejoin="miter" />
        <path d="M14 61 H47" fill="none" stroke="#CACFC8" strokeWidth="2" />
      </svg>
    </div>
