export const GeneratedShot = (props: any) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cueDefaults: Record<number, [number, number, string]> = {
    22: [0, 14, 'Sounds'], 23: [13, 36, 'perfect,'], 24: [33, 48, 'right?'],
    25: [95, 108, "It's"], 26: [107, 152, 'transparent,'], 27: [179, 195, "it's"], 28: [202, 258, 'decentralized.'],
    29: [277, 309, 'Nobody'], 30: [308, 322, 'can'], 31: [323, 354, 'secretly'], 32: [352, 375, 'change'],
    33: [374, 385, 'the'], 34: [382, 406, 'votes.'], 35: [451, 462, 'So'], 36: [458, 470, 'why'],
    37: [467, 479, "don't"], 38: [476, 484, 'we'], 39: [482, 495, 'just'], 40: [493, 506, 'put'],
    41: [504, 543, 'elections'], 42: [540, 551, 'on'], 43: [547, 578, 'blockchain?']
  };
  const getCue = (id: number) => {
    const explicit = cues.find((c: any) => Number(c.wordIndex ?? c.index ?? c.id) === id || String(c.id) === 'W' + id);
    if (explicit) return explicit;
    if (cues.length === 22) return cues[id - 22];
    if (cues.length > 43) return cues[id];
    return undefined;
  };
  const at = (id: number) => Number(getCue(id)?.startFrame ?? cueDefaults[id][0]);
  const end = (id: number) => Number(getCue(id)?.endFrame ?? cueDefaults[id][1]);
  const pop = (start: number, stiffness = 160) => spring({ frame: Math.max(0, frame - start), fps, config: { damping: 14, stiffness, mass: 0.8 } });
  const last = Math.max(579, durationInFrames - 1);
  const revealStart = Math.min(end(24) + 6, at(25) - 40);
  const reveals = [0, revealStart, revealStart + 5, revealStart + 10, revealStart + 15, revealStart + 20, revealStart + 25];
  const visibleCount = reveals.filter((f) => frame >= f).length;
  const allVisible = reveals[6] + 12;
  const boundaryStart = at(35);
  const pullbackEnd = end(43);
  const footprint = range(frame, end(24) - 6, at(25) - 6);
  const altered = frame >= at(32);
  const alterMix = range(frame, at(32), at(32) + 10);
  const boundaryMix = range(frame, boundaryStart, pullbackEnd);
  const quoteIn = range(frame, at(35), at(35) + 12);
  const ghostOpacity = frame >= allVisible ? 0.03 * range(frame, allVisible, allVisible + 14) : 0;
  const camFrames = [0, end(24), at(25), at(26), end(26), at(28), end(28), at(29), at(31), at(32), end(34), at(35), at(41), end(43), last];
  const zoom = interpolate(frame, camFrames, [1.04, 1.00, 1.00, 1.00, 1.14, 1.14, 1.20, 1.20, 1.23, 1.26, 1.26, 1.26, 1.09, 1.00, 1.025], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
  const panX = interpolate(frame, camFrames, [24, 0, 0, 0, 56, 56, -104, -104, 72, 154, 154, 154, 28, 0, -13], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
  const panY = interpolate(frame, camFrames, [0, 0, 0, 0, 8, 8, 5, 5, 24, 34, 34, 34, 10, 0, -2], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
  const localZoom = range(frame, at(24), end(24), 1.6, 1);
  const inspection = range(frame, at(29), at(31));
  const focusVisible = range(frame, at(31), at(31) + 9);
  const focus = {
    x: interpolate(boundaryMix, [0, 1], [611, 42]),
