            {changed ? <div style={{ width: 8, height: 8, border: '1.5px solid ' + C.coral, transform: 'rotate(45deg)' }} /> : <svg width="11" height="9" viewBox="0 0 11 9"><path d="M1 4.5 L4 7.5 L10 1.5" fill="none" stroke={C.teal} strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" /></svg>}
          </div>
        </div>;
      })}
    </div>
  );

  return (
