        <AbsoluteFill style={{ opacity: 0.36 }}><mg.GridBackground mode="light" gridSize={48} /></AbsoluteFill>
        <mg.Noise opacity={0.04} />
        <div style={{ position: 'absolute', left: 80, top: 170, width: 1760, height: 850, overflow: 'hidden', borderRadius: 26, background: 'linear-gradient(125deg, rgba(255,255,255,0.48) 0%, rgba(255,255,255,0.17) 54%, rgba(224,233,228,0.28) 100%)', border: '1px solid rgba(255,255,255,0.8)', boxSizing: 'border-box', boxShadow: '0 28px 80px rgba(20,37,54,0.045), inset 0 1px 0 rgba(255,255,255,0.95)' }}>
