const timing = [
  [44, 0, 19, 'Because'], [45, 28, 43, 'the'], [46, 40, 64, 'biggest'], [47, 65, 94, 'problem'],
  [48, 90, 102, 'with'], [49, 99, 141, 'elections'], [50, 162, 183, "isn't"], [51, 183, 213, 'storing'],
  [52, 209, 220, 'the'], [53, 216, 241, 'votes.'], [54, 284, 295, "It's"], [55, 292, 316, 'making'],
  [56, 312, 331, 'sure'], [57, 329, 346, 'the'], [58, 373, 395, 'right'], [59, 398, 427, 'person'],
  [60, 423, 431, 'is'], [61, 430, 458, 'casting'], [62, 454, 465, 'the'], [63, 461, 478, 'vote']
] as const;

const normalize = (s: string) => s.toLowerCase().replace(/[^a-z]/g, '');
const ease = Easing.bezier(0.42, 0, 0.2, 1);
const mix = (a: number, b: number, t: number) => a + (b - a) * t;
const blendRect = (a: Rect, b: Rect, t: number): Rect => ({ x: mix(a.x, b.x, t), y: mix(a.y, b.y, t), w: mix(a.w, b.w, t), h: mix(a.h, b.h, t) });

const VoteTile: React.FC<{ size?: number }> = ({ size = 100 }) => (
  <div style={{ position: 'relative', width: size, height: size, flexShrink: 0, filter: 'drop-shadow(0 7px 7px rgba(20,37,54,0.11))' }}>
    <div style={{ position: 'absolute', inset: 0, background: 'linear-gradient(145deg, #FFFDF4 0%, #F3EEE0 76%, #EAE3D3 100%)', clipPath: 'polygon(0 0, 77% 0, 100% 23%, 100% 100%, 0 100%)', borderRadius: 10 }} />
    <div style={{ position: 'absolute', inset: 0, background: C.coral, clipPath: 'polygon(77% 0, 100% 23%, 77% 23%)' }} />
    <div style={{ position: 'absolute', left: '20%', top: '24%', width: '56%', height: '57%', border: '1px solid rgba(20,37,54,0.15)', borderRadius: 5 }} />
    <div style={{ position: 'absolute', left: '44%', top: '38%', width: '12%', height: '33%', borderRadius: 2, background: C.ink, transform: 'rotate(32deg)' }} />
  </div>
);

const Relationship: React.FC<{ frame: number; cue: number; end: number; fps: number }> = ({ frame, cue, end, fps }) => {
  const pulse = frame < cue ? 0 : spring({ frame: frame - cue, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const opacity = interpolate(frame, [cue, end], [0.56, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  return (
    <svg width={220} height={102} viewBox="0 0 220 102" style={{ display: 'block', overflow: 'visible' }} aria-label="Two relationship segments remain separated">
      <path d="M110 0V26 M110 76V102" stroke={C.ink} strokeWidth={2.5} fill="none" strokeLinecap="round" />
      <circle cx={110} cy={26} r={4} fill={C.white} stroke={C.ink} strokeWidth={1.5} />
      <circle cx={110} cy={76} r={4} fill={C.white} stroke={C.ink} strokeWidth={1.5} />
      <g opacity={opacity} transform={'translate(110 51) scale(' + (0.97 + pulse * 0.03) + ') translate(-110 -51)'}>
        <path d="M92 35H81V67H92 M128 35H139V67H128" stroke={C.coral} strokeWidth={3} fill="none" strokeLinecap="square" />
      </g>
    </svg>
  );
};

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const themeMode = 'light' as const;
  const s = Math.min(width / 1920, height / 1080);
  const cueFor = (index: number) => {
    const explicit = cues.find(c => c.wordIndex === index || c.index === index || c.id === index || c.id === 'W' + index);
    if (explicit) return explicit;
    const local = timing[index - 44];
    if (cues.length === timing.length) return cues[index - 44];
    return cues.find(c => normalize(c.word || c.text || '') === normalize(local[3]) && Math.abs((c.startFrame ?? -999) - local[1]) < 48);
  };
  const start = (index: number) => cueFor(index)?.startFrame ?? timing[index - 44][1];
  const end = (index: number) => cueFor(index)?.endFrame ?? timing[index - 44][2];
  const progress = (a: number, b: number) => interpolate(frame, [a, Math.max(a + 1, b)], [0, 1], { easing: ease, extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const structural = spring({ frame: Math.max(0, frame - 2), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const residual = frame < 2 ? 1 : (1 - structural) * (1 - progress(12, end(44)));
  const structureY = 11 * residual;
  const ledgerTilt = -2 - residual * 0.6;
  const heroScale = 1 + residual * 0.035;
  const storageInspect = progress(start(50), end(53));
  const travelStart = start(54);
  const titleArrive = end(58);
  const relationArrive = end(59);
  const wideStart = Math.max(479, end(63) + 1);
  const wideEnd = Math.min(550, durationInFrames - 25);
  const last = Math.max(wideEnd + 1, durationInFrames - 1);

  const stage = { x: 80, y: 170, w: 1760, h: 870 };
  const left = { x: 80, y: 30, w: 700, h: 810, tilt: 1 };
  const right = { x: 980, y: 30, w: 700, h: 810, tilt: ledgerTilt };
  const cardPoint = (card: typeof left, x: number, y: number) => {
    const r = card.tilt * Math.PI / 180;
    const dx = x - card.w / 2;
    const dy = y - card.h / 2;
    return { x: card.x + card.w / 2 + dx * Math.cos(r) - dy * Math.sin(r), y: card.y + card.h / 2 + dx * Math.sin(r) + dy * Math.cos(r) + (card.x === right.x ? structureY : 0) };
  };
  const pTile = cardPoint(right, 338, 375);
  const pRow = cardPoint(right, 350, 375);
  const pTitle = cardPoint(left, 350, 95);
  const pCredential = cardPoint(left, 350, 258);
  const pRelation = cardPoint(left, 350, 481);
  const tileRect: Rect = { x: pTile.x, y: pTile.y, w: 132, h: 132 };
  const rowRect: Rect = { x: pRow.x, y: pRow.y, w: 606, h: 150 };
  const titleRect: Rect = { x: pTitle.x, y: pTitle.y, w: 610, h: 124 };
  const relationRect: Rect = { x: pRelation.x, y: pRelation.y, w: 590, h: 286 };
  const expandedRect = blendRect(tileRect, rowRect, storageInspect);
  const titleTravel = progress(travelStart, titleArrive);
  const relationTravel = progress(titleArrive, relationArrive);
  let focusRect = expandedRect;
  let focusAngle = ledgerTilt;
  if (frame >= travelStart && frame < titleArrive) {
    focusRect = blendRect(rowRect, titleRect, titleTravel);
    focusRect.y -= Math.sin(Math.PI * titleTravel) * 25;
    focusAngle = mix(ledgerTilt, 1, titleTravel);
  } else if (frame >= titleArrive) {
    focusRect = blendRect(titleRect, relationRect, relationTravel);
    focusAngle = 1;
  }
  const global = (p: { x: number; y: number }) => ({ x: stage.x + p.x, y: stage.y + p.y });
  const tileGlobal = global(pTile);
  const relationGlobal = global(pRelation);
  const cameraAt = [0, end(44), end(49), start(50), end(53), travelStart, titleArrive, relationArrive, wideStart, wideEnd, last];
  const zoom = interpolate(frame, cameraAt, [1.28, 1.28, 1.12, 1.12, 1.23, 1.23, 1.21, 1.23, 1.23, 1, 1.015], { easing: ease, extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const aimX = interpolate(frame, cameraAt, [tileGlobal.x + 42, tileGlobal.x + 42, 1345, 1345, 1380, 1380, 625, relationGlobal.x, relationGlobal.x, 960, 960], { easing: ease, extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const aimY = interpolate(frame, cameraAt, [tileGlobal.y - 4, tileGlobal.y - 4, 588, 588, 576, 576, 515, 607, 607, 540, 540], { easing: ease, extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const panX = 960 - aimX;
  const panY = 540 - aimY;
  const focusOpacity = 1 - progress(wideStart, wideEnd) * 0.14;
  const ringPulse = frame >= relationArrive && frame < wideStart ? 0.1 + 0.055 * Math.sin((frame - relationArrive) * 0.07) : 0.08;
  const eventPulse = frame >= start(61) ? spring({ frame: frame - start(61), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } }) : 0;
  const headingOpacity = interpolate(frame, [2, 19], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
