        <div style={{ position: 'absolute', left: 1380 - frame * 0.24, top: 140, width: 390, height: 780, background: 'linear-gradient(90deg, transparent, rgba(255,255,255,0.22), transparent)', transform: 'rotate(24deg)', filter: 'blur(30px)' }} />

        <mg.CameraRig zoom={zoom} x={panX} y={panY}>
          <div style={{ position: 'absolute', left: stage.x, top: stage.y, width: stage.w, height: stage.h }}>
            <div style={{ position: 'absolute', left: left.x + 32, top: 766, width: 636, height: 75, borderRadius: '50%', background: 'rgba(29,48,43,0.12)', filter: 'blur(33px)' }} />
            <div style={{ position: 'absolute', left: right.x + 32, top: 766 + structureY, width: 636, height: 75, borderRadius: '50%', background: 'rgba(29,48,43,0.12)', filter: 'blur(33px)' }} />

            <div style={{ position: 'absolute', left: left.x, top: left.y, width: 700, height: 810, filter: 'drop-shadow(0 20px 31px rgba(20,37,54,0.055))' }}>
