import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, interpolate, spring, Easing } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { wordIndex?: number; index?: number; word?: string; text?: string; startFrame: number; endFrame?: number };
type ShotProps = { wordCues?: WordCue[] };

const C = { porcelain: "#F3F1EB", white: "#FFFFFF", navy: "#142536", slate: "#627383", teal: "#087F79", coral: "#ED705F", rule: "#D5DDD9" };
const sans = '"Inter", "Arial", sans-serif';
const tight = '"Inter Tight", "Inter", "Arial", sans-serif';
const mono = '"IBM Plex Mono", "Courier New", monospace';
const words = ["But", "here's", "the", "problem.", "An", "election", "isn't", "just", "a", "database", "problem.", "Imagine", "I", "vote", "from", "my", "phone."];
const defaults = [0, 2, 16, 20, 88, 96, 128, 150, 170, 178, 212, 286, 308, 322, 336, 346, 354];
const normalize = (value: string) => value.toLowerCase().replace(/[’]/g, "'").replace(/[^a-z']/g, "");
const ease = Easing.bezier(0.42, 0, 0.22, 1);
const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

// Exactly ten SVG shapes: body, bezel, screen, speaker, five rows, submit area.
const PhoneGraphic: React.FC = () => (
  <svg width="520" height="800" viewBox="0 0 520 800" role="img" aria-label="Illustrative phone with neutral selections and inactive submit area">
    <rect x="7" y="7" width="506" height="786" rx="65" fill={C.navy} stroke="#314351" strokeWidth="2" />
    <rect x="23" y="23" width="474" height="754" rx="53" fill="#243747" stroke="#435260" strokeWidth="1.5" />
    <rect x="40" y="44" width="440" height="712" rx="38" fill="#F7F4EC" />
    <rect x="201" y="62" width="118" height="10" rx="5" fill={C.navy} opacity="0.74" />
    <rect x="83" y="176" width="354" height="51" rx="8" fill="#DDE1DD" />
    <rect x="83" y="263" width="354" height="51" rx="8" fill="#DDE1DD" />
    <rect x="83" y="350" width="354" height="51" rx="8" fill="#DDE1DD" />
    <rect x="83" y="437" width="354" height="51" rx="8" fill="#DDE1DD" />
    <rect x="83" y="524" width="354" height="51" rx="8" fill="#DDE1DD" />
    <rect x="83" y="647" width="354" height="59" rx="12" fill="#E4E5DE" stroke="#CFD5D0" strokeWidth="1.5" />
  </svg>
);

const VoteTile: React.FC<{ size?: number; opacity?: number }> = ({ size = 90, opacity = 1 }) => (
  <div style={{ width: size, height: size, opacity, position: "relative", filter: "drop-shadow(0 8px 12px rgba(20,37,54,0.10))" }}>
    <div style={{ position: "absolute", inset: 0, background: "linear-gradient(145deg, #FFFCF4 0%, #F2EDE0 100%)", clipPath: "polygon(0 0, 77% 0, 100% 23%, 100% 100%, 0 100%)", borderRadius: 10, border: "1px solid #D6D7CD" }} />
    <div style={{ position: "absolute", right: 0, top: 0, width: "24%", height: "24%", background: C.coral, clipPath: "polygon(0 0, 0 100%, 100% 100%)" }} />
    <div style={{ position: "absolute", left: "33%", top: "30%", width: "12%", height: "41%", background: C.navy, borderRadius: 2 }} />
    <div style={{ position: "absolute", left: "51%", top: "45%", width: "12%", height: "26%", background: C.navy, borderRadius: 2 }} />
  </div>
);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const themeMode = "light" as const;
  const cueStart = (wordIndex: number) => {
    const local = wordIndex - 105;
    const explicit = cues.find((cue) => cue.wordIndex === wordIndex || cue.index === wordIndex);
    const positional = cues.length === words.length ? cues[local] : undefined;
    const global = cues.length > wordIndex ? cues[wordIndex] : undefined;
    const candidate = explicit || positional || global;
    if (candidate && Number.isFinite(candidate.startFrame)) return candidate.startFrame;
    const expected = normalize(words[local] || "");
    const matches = cues.filter((cue) => normalize(cue.word || cue.text || "") === expected && Number.isFinite(cue.startFrame));
    if (matches.length) return matches.reduce((a, b) => Math.abs(a.startFrame - defaults[local]) < Math.abs(b.startFrame - defaults[local]) ? a : b).startFrame;
    return defaults[local];
  };
  const opening = cueStart(105);
  const here = cueStart(106);
  const problem = cueStart(108);
  const sentence = cueStart(109);
  const election = cueStart(110);
  const not = cueStart(111);
  const just = cueStart(112);
  const database = cueStart(114);
  const secondProblem = cueStart(115);
  const imagine = cueStart(116);
  const iWord = cueStart(117);
  const vote = cueStart(118);
  const from = cueStart(119);
  const my = cueStart(120);
  const phone = cueStart(121);
  const driftEnd = imagine - 1;
  const pullbackEnd = secondProblem + 28;
  const phoneEnd = phone + 17;
  const lastFrame = Math.max(phoneEnd + 2, durationInFrames - 1);
  const clamp01 = (n: number) => Math.min(1, Math.max(0, n));
  const progress = (start: number, end: number, easing = ease) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing });
  const snap = (at: number) => spring({ frame: frame - at, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });

  const openingMove = progress(opening, problem + 23);
  const investigation = progress(sentence, pullbackEnd);
  const emptyDrift = progress(pullbackEnd, driftEnd, Easing.linear);
  const arrivalMove = progress(imagine, phoneEnd);
  const handoff = progress(phoneEnd + 1, lastFrame);
  const zoom = frame < sentence ? lerp(1.24, 1.16, openingMove) : frame < pullbackEnd ? lerp(1.16, 1.0, investigation) : frame < imagine ? 1.0 : frame <= phoneEnd ? lerp(1.0, 1.20, arrivalMove) : lerp(1.20, 1.10, handoff);
  const targetX = frame < sentence ? lerp(1300, 1250, openingMove) : frame < pullbackEnd ? lerp(1250, 900, investigation) : frame < imagine ? lerp(900, 875, emptyDrift) : frame <= phoneEnd ? lerp(875, 810, arrivalMove) : lerp(810, 745, handoff);
  const targetY = frame < sentence ? lerp(492, 490, openingMove) : frame < pullbackEnd ? lerp(490, 520, investigation) : frame < imagine ? 520 : frame <= phoneEnd ? lerp(520, 480, arrivalMove) : lerp(480, 482, handoff);
  const panX = (880 - targetX) * zoom;
  const panY = (425 - targetY) * zoom;

  const phoneSpring = frame >= imagine ? snap(imagine) : 0;
  const phonePresence = progress(imagine, imagine + 14, Easing.linear);
  const phoneLeft = 570;
  const phoneTop = 46 + (1 - phoneSpring) * 520;
  const ledgerRetreat = progress(election, pullbackEnd);
  const ledgerScale = lerp(1, 0.70, ledgerRetreat);
  const ledgerLeft = lerp(1050, 1310, ledgerRetreat);
  const ledgerTop = lerp(318, 382, ledgerRetreat);
  const ledgerWidth = 636;
  const ledgerHeight = 360;
  const ledgerRailY = ledgerTop + 184 * ledgerScale;
  const railStart = 900;
  const railEnd = ledgerLeft + 6;
  const railPath = `M ${railStart} 692 C 1138 692, ${railEnd - 195} ${ledgerRailY}, ${railEnd} ${ledgerRailY}`;
  const broadPath = `M ${railStart} 692 C 1138 692, ${railEnd - 190} ${ledgerRailY}, ${railEnd} ${ledgerRailY}`;
  const revealWidth = lerp(292, 2120, progress(sentence, pullbackEnd));
  const revealLeft = railEnd + 35 - revealWidth;

  const inspectionArrival = frame >= problem ? snap(problem) : 0;
  const reshape = progress(imagine, my);
  const focusStart = { x: 1033, y: 299, w: 670, h: 399 };
  const focusFinish = { x: phoneLeft - 24, y: 27, w: 568, h: 838 };
  const focusX = lerp(focusStart.x, focusFinish.x, reshape);
  const focusY = lerp(focusStart.y, focusFinish.y, reshape) + Math.sin(reshape * Math.PI) * 48;
  const focusW = lerp(focusStart.w, focusFinish.w, reshape);
  const focusH = lerp(focusStart.h, focusFinish.h, reshape);
  const focusAlpha = frame < problem ? 0 : frame < sentence ? clamp01(inspectionArrival) * 0.91 : frame < imagine ? lerp(0.91, 0.14, progress(sentence, just + 20)) : lerp(0.14, 0.82, progress(imagine, iWord + 5));
  const focusRadius = lerp(24, 83, reshape);
  const focusScale = frame < sentence ? lerp(1.055, 1, inspectionArrival) : 1;
  const inputLabel = progress(imagine, iWord + 5);
  const sourceTileAlpha = progress(vote, vote + 12);
  const stageFit = Math.min(width / 1920, height / 1080);
  const inputGlow = lerp(0.035, 0.12, progress(sentence, phone));

  return (
    <AbsoluteFill style={{ background: "linear-gradient(154deg, #FCFAF5 0%, #F3F1EB 39%, #E8EDE8 76%, #EEECE6 100%)", overflow: "hidden", color: C.navy, fontFamily: sans }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920 * stageFit) / 2, top: (height - 1080 * stageFit) / 2, transform: `scale(${stageFit})`, transformOrigin: "0 0", overflow: "hidden" }}>
        <AbsoluteFill style={{ background: "radial-gradient(66% 78% at 78% 19%, rgba(255,255,255,0.94) 0%, rgba(255,255,255,0.22) 45%, transparent 74%), radial-gradient(56% 72% at 11% 72%, rgba(237,112,95,0.055), transparent 75%)" }} />

        <div style={{ position: "absolute", left: 80, top: 192, width: 1760, height: 850 }}>
          <mg.CameraRig zoom={zoom} x={panX} y={panY}>
            <div style={{ width: 1760, height: 850, position: "relative", isolation: "isolate" }}>
              <div style={{ position: "absolute", left: -850, top: -850, width: 3460, height: 2550, background: "linear-gradient(158deg, #FAF8F2 0%, #F3F1EB 43%, #E9EEE8 72%, #F4F1E9 100%)", pointerEvents: "none" }}>
                <mg.GridBackground mode={themeMode} gridSize={48} />
                <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(243,241,235,0.14), rgba(243,241,235,0.40)), radial-gradient(52% 58% at 61% 39%, rgba(255,255,255,0.84), transparent 75%)" }} />
                <AbsoluteFill style={{ background: `radial-gradient(650px 640px at 1530px 1280px, rgba(237,112,95,${inputGlow}), transparent 76%), radial-gradient(720px 550px at 2390px 1220px, rgba(8,127,121,0.07), transparent 75%)` }} />
              </div>

              <div aria-hidden style={{ position: "absolute", left: -212 - frame * 0.075, top: -135, fontFamily: tight, fontWeight: 600, fontSize: 880, lineHeight: 1, letterSpacing: -85, color: C.navy, opacity: 0.03, userSelect: "none" }}>06</div>
              <div style={{ position: "absolute", left: -510, top: 775, width: 2700, height: 1, background: "linear-gradient(90deg, transparent, rgba(20,37,54,0.16) 24%, rgba(20,37,54,0.13) 82%, transparent)" }} />
              <div style={{ position: "absolute", left: 1052, top: 764, width: 623, height: 30, background: "radial-gradient(ellipse at center, rgba(20,37,54,0.12), transparent 72%)", filter: "blur(15px)", opacity: 1 - ledgerRetreat * 0.40 }} />

              <mg.Marker x={120} y={118} variant="cross" color={C.rule} />
              <mg.Marker x={1725} y={118} variant="cross" color={C.rule} />
              <mg.Marker x={120} y={810} variant="cross" color={C.slate} />
              <mg.Marker x={1725} y={810} variant="cross" color={C.rule} />
              <div style={{ opacity: lerp(0.12, 0.5, investigation) }}>
                <mg.Marker x={368} y={514} variant="cross" color={C.coral} />
              </div>

              <svg width="2360" height="930" viewBox="-480 0 2360 930" style={{ position: "absolute", left: -480, top: 0, overflow: "visible" }} aria-hidden>
                <defs>
                  <linearGradient id="s06-conduit" x1="880" y1="690" x2="1450" y2="520" gradientUnits="userSpaceOnUse">
                    <stop offset="0" stopColor="#ECE5DB" />
                    <stop offset="0.43" stopColor="#E1E4DB" />
                    <stop offset="1" stopColor="#D9E6DF" />
                  </linearGradient>
                  <linearGradient id="s06-rail" x1="-520" y1="0" x2="1430" y2="0" gradientUnits="userSpaceOnUse">
                    <stop offset="0" stopColor={C.navy} stopOpacity="0" />
                    <stop offset="0.26" stopColor={C.navy} stopOpacity="0.40" />
                    <stop offset="0.8" stopColor={C.navy} stopOpacity="0.68" />
                    <stop offset="1" stopColor={C.navy} stopOpacity="0.86" />
                  </linearGradient>
                  <filter id="s06-rail-shadow" x="-30%" y="-100%" width="160%" height="300%">
                    <feGaussianBlur stdDeviation="15" />
                  </filter>
                  <clipPath id="s06-upstream-reveal"><rect x={revealLeft} y="300" width={revealWidth} height="475" /></clipPath>
                </defs>
                <g clipPath="url(#s06-upstream-reveal)">
                  <path d={broadPath} fill="none" stroke={C.navy} strokeWidth="80" opacity="0.055" filter="url(#s06-rail-shadow)" transform="translate(0 16)" />
                  <path d={broadPath} fill="none" stroke="#CCD9D2" strokeWidth="89" opacity="0.59" />
                  <path d={broadPath} fill="none" stroke="url(#s06-conduit)" strokeWidth="84" />
                  <path d={broadPath} fill="none" stroke="#FFFFFF" strokeWidth="1.8" opacity="0.75" transform="translate(0 -40)" />
                </g>
                <path d={`M -550 ${ledgerRailY} L ${railEnd} ${ledgerRailY}`} fill="none" stroke="url(#s06-rail)" strokeWidth="1.8" opacity={1 - progress(sentence, secondProblem) * 0.92} />
                <path d={railPath} fill="none" stroke={C.navy} strokeWidth="2.1" opacity={lerp(0.05, 0.60, investigation)} clipPath="url(#s06-upstream-reveal)" />
              </svg>

              <div style={{ position: "absolute", left: 1129, top: 752, opacity: progress(database, secondProblem + 8) * (1 - arrivalMove * 0.16), fontFamily: sans, fontSize: 28, fontWeight: 500, letterSpacing: -0.4, color: C.slate }}>Illustrative transmission path</div>

              <div style={{ position: "absolute", left: ledgerLeft, top: ledgerTop, width: ledgerWidth, height: ledgerHeight, transform: `scale(${ledgerScale})`, transformOrigin: "0 0", zIndex: 5 }}>
                <div style={{ position: "absolute", inset: "32px 10px -20px 12px", background: "rgba(20,37,54,0.115)", borderRadius: 27, filter: "blur(24px)" }} />
                <mg.Card width={ledgerWidth} height={ledgerHeight} tilt={-2} mode="light">
                  <div style={{ position: "absolute", inset: 0, borderRadius: 25, overflow: "hidden", background: "linear-gradient(146deg, #FFFFFF 0%, #FBFCF9 57%, #EAF3EC 100%)", border: "1px solid rgba(151,175,163,0.48)", boxShadow: "inset 0 1px 0 rgba(255,255,255,0.96), 0 12px 34px rgba(20,37,54,0.05)" }}>
                    <div style={{ position: "absolute", left: 32, top: 30, fontFamily: sans, fontSize: 31, fontWeight: 500, letterSpacing: -0.8, color: C.navy }}>Illustrative record model</div>
