  const cues = props.wordCues || [];
  const themeMode = 'dark' as const;
  const resolveCue = (id: number, text: string, fallback: number) => {
    const indexed = cues.find(c => c.wordIndex === id || c.globalIndex === id || c.index === id);
    const normalized = text.toLowerCase().replace(/[^a-z]/g, '');
    const verbal = cues.find(c => (c.word || c.text || '').toLowerCase().replace(/[^a-z]/g, '') === normalized);
    const positional = cues.length === 11 ? cues[id - 167] : undefined;
    const cue = indexed || verbal || positional;
    return typeof cue?.startFrame === 'number' ? cue.startFrame : fallback;
  };
  const at = {
    and: resolveCue(167, 'And', 0), elections: resolveCue(168, 'elections', 44),
    require: resolveCue(169, 'require', 117), something: resolveCue(170, 'something', 151),
    extremely: resolveCue(171, 'extremely', 181), important: resolveCue(172, 'important', 233),
    your: resolveCue(173, 'Your', 308), vote: resolveCue(174, 'vote', 321),
    must: resolveCue(175, 'must', 343), be: resolveCue(176, 'be', 364), secret: resolveCue(177, 'secret', 379)
