  const ramp = (start: number, end: number, outA = 0, outB = 1) => interpolate(frame, [start, Math.max(start + 1, end)], [outA, outB], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: ease });
  const snap = (delay: number) => spring({ frame: Math.max(0, frame - delay), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
