export const GeneratedShot = (props: any) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const cue = (index: number, fallback: number): number => {
    const found = cues.find((item: any) => Number(item.wordIndex ?? item.index ?? item.id) === index);
    const local = found || (cues.length === 34 ? cues[index - 178] : undefined);
    const value = local?.startFrame ?? local?.start;
    return typeof value === "number" && Number.isFinite(value) ? value : fallback;
  };
  const verifyA = cue(184, 97);
  const voted = Math.max(verifyA + 1, cue(187, 144));
  const second = Math.max(voted + 1, cue(188, 207));
  const verifyB = Math.max(second + 1, cue(193, 249));
  const eligible = Math.max(verifyB + 1, cue(197, 300));
  const vote = Math.max(eligible + 1, cue(199, 333));
  const pivot = Math.max(vote + 1, cue(200, 390));
  const not = Math.max(pivot + 1, cue(203, 432));
  const determine = Math.max(not + 1, cue(207, 483));
  const who = Math.max(determine + 1, cue(208, 511));
  const forWord = Math.max(who + 1, cue(211, 538));
  const end = Math.max(forWord + 2, durationInFrames - 1);
  const camFrames = [0, voted, second, verifyB, vote, pivot, not, determine, forWord, end];
  const zoom = interpolate(frame, camFrames, [1.26, 1.22, 1.22, 1.235, 1.24, 1.24, 1, 1, 1.06, 1], cameraOptions);
  const panX = interpolate(frame, camFrames, [226, 195, 195, 200, 207, 207, 0, 0, 22, 0], cameraOptions);
  const panY = interpolate(frame, camFrames, [105, 84, 84, -125, -140, -140, 0, 0, -10, 0], cameraOptions);
  const enterA = spring({ frame, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const enterB = spring({ frame: frame - 5, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const enterC = spring({ frame: frame - 10, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const appearA = Math.min(1, 0.88 + enterA * 0.12);
  const appearB = Math.min(1, 0.85 + enterB * 0.15);
  const appearC = Math.min(1, 0.88 + enterC * 0.12);
  const activeA = interpolate(frame, [0, verifyA, voted, second, verifyB], [0.3, 1, 1, 1, 0.22], clampOptions);
  const activeB = interpolate(frame, [0, second, verifyB, vote, pivot, not], [0.14, 0.14, 1, 1, 1, 0.3], clampOptions);
  const inspectionA = interpolate(frame, [verifyA, verifyA + 10], [0, 1], clampOptions);
  const inspectionB = interpolate(frame, [verifyB, verifyB + 10], [0, 1], clampOptions);
  const scanA = interpolate(frame, [verifyA, voted + 36, second], [0, 0.88, 0.92], cameraOptions);
  const scanB = interpolate(frame, [verifyB, eligible, vote + 24], [0, 0.57, 0.91], cameraOptions);
  const focusFrames = [0, second, verifyB, pivot, not, end];
  const focusX = interpolate(frame, focusFrames, [0, 0, 0, 0, 880, 880], cameraOptions);
  const focusY = interpolate(frame, focusFrames, [0, 0, 400, 400, 0, 0], cameraOptions);
  const focusW = interpolate(frame, focusFrames, [820, 820, 820, 820, 880, 880], cameraOptions);
  const focusH = interpolate(frame, focusFrames, [360, 360, 360, 360, 760, 760], cameraOptions);
  const focusTilt = interpolate(frame, [pivot, not], [-2, 0], cameraOptions);
  const focusPop = spring({ frame: frame - 18, fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const focusOpacity = interpolate(frame, [18, 28, pivot, not], [0, 0.38, 0.38, 0.8], clampOptions);
  const boundary = interpolate(frame, [pivot, not], [0.26, 1], cameraOptions);
  const rightLabel = interpolate(frame, [determine, who], [0.77, 1], cameraOptions);
  const attempt = interpolate(frame, [determine, forWord], [0, 1], cameraOptions);
  const handoff = interpolate(frame, [forWord + 10, end], [0, 1], cameraOptions);
  const layoutScale = Math.min(width / 1920, height / 1080);
  const themeMode = "light" as const;

