type WordCue = {
  wordIndex?: number;
  index?: number;
  word?: string;
  text?: string;
  startFrame?: number;
  endFrame?: number;
};

type ShotProps = { wordCues?: WordCue[] };

const C = {
  field: "#F3F1EB",
  white: "#FFFFFF",
  ink: "#142536",
  slate: "#627383",
