    const normalize = (value: string) => value.toLowerCase().replace(/[^a-z]/g, "");
    const cue = cues.find((item) => item.wordIndex === index || item.index === index) || cues.find((item) => normalize(item.word || item.text || "") === normalize(text));
    const value = cue?.[edge];
    return typeof value === "number" && Number.isFinite(value) ? value : fallback;
