type WordCue = {
  wordIndex?: number;
  index?: number;
  id?: number | string;
  word?: string;
  text?: string;
  startFrame?: number;
};
type ShotProps = { wordCues?: WordCue[] };
type Rect = { x: number; y: number; w: number; h: number; r: number };

const P = {
  paper: "#F3F1EB",
  white: "#FFFFFF",
  ink: "#142536",
  slate: "#627383",
  teal: "#087F79",
  coral: "#ED705F",
  rule: "#D5DDD9"
};
