  const cueAt = (index: number, fallback: number, word: string): number => {
    const found = cues.find((cue) => {
      const id = cue.wordIndex ?? cue.index ?? cue.id;
      return id === index || id === `W${index}` || id === String(index);
    }) || cues.find((cue) => (cue.word || cue.text || "").toLowerCase().replace(/[^a-z]/g, "") === word);
    return found && typeof found.startFrame === "number" ? found.startFrame : fallback;
  };
