];
const clamp = (n: number, a = 0, b = 1) => Math.max(a, Math.min(b, n));
const smooth = Easing.bezier(0.32, 0, 0.18, 1);
const easeOut = Easing.bezier(0.18, 0.72, 0.25, 1);
const mix = (a: number, b: number, t: number) => a + (b - a) * t;
const phase = (frame: number, a: number, b: number, easing = smooth) => interpolate(frame, [a, Math.max(a + 1, b)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing });
const bead = (p0: Point, p1: Point, p2: Point, p3: Point, t: number): Point => {
  const q = 1 - t;
  return { x: q * q * q * p0.x + 3 * q * q * t * p1.x + 3 * q * t * t * p2.x + t * t * t * p3.x, y: q * q * q * p0.y + 3 * q * q * t * p1.y + 3 * q * t * t * p2.y + t * t * t * p3.y };
};
const routePoint = (t: number): Point => {
  if (t <= 0.5) return bead({ x: 366, y: 438 }, { x: 558, y: 438 }, { x: 626, y: 312 }, { x: 822, y: 342 }, t * 2);
  return bead({ x: 822, y: 342 }, { x: 1020, y: 372 }, { x: 1138, y: 444 }, { x: 1340, y: 438 }, (t - 0.5) * 2);
};
const tangent = (t: number) => {
  const a = routePoint(clamp(t - 0.002));
  const b = routePoint(clamp(t + 0.002));
  return Math.atan2(b.y - a.y, b.x - a.x) * 180 / Math.PI;
};
const RECORD_PATH = 'M 366 438 C 558 438 626 312 822 342 C 1020 372 1138 444 1340 438';
const ROUTES: RouteSpec[] = [
