    const exact = cues.find(c => c.wordIndex === id || c.index === id || String(c.id) === 'W' + id || String(c.id) === String(id));
    const ordered = cues.length === LOCAL_CUES.length ? cues[id - 267] : undefined;
    const cue = exact || ordered;
    return cue && typeof cue.startFrame === 'number' ? cue.startFrame : local[1];
