              <div style={{ position: 'absolute', left: 360, top: 170, width: 1030, height: 500, background: 'radial-gradient(ellipse, rgba(255,255,255,0.75) 0%, rgba(210,220,215,0.17) 57%, transparent 73%)', filter: 'blur(30px)', transform: 'translateX(' + (dense * 25 - exitDrift * 40) + 'px)' }} />

