    if (identified && typeof identified.startFrame === "number") return identified.startFrame;
    const normalize = (value: string) => value.toLowerCase().replace(/[^a-z']/g, "");
    const positional = cues.length === LOCAL_WORDS.length ? cues[wordIndex - 290] : cues[wordIndex];
    if (positional && typeof positional.startFrame === "number") {
      const text = positional.word || positional.text || "";
      if (!text || normalize(text) === normalize(LOCAL_WORDS[wordIndex - 290] || "")) return positional.startFrame;
