  { x: 558, y: 624, w: 278, h: 94, target: 531 },
  { x: 90, y: 699, w: 262, h: 94, target: 591 }
];
const ROUTES = NODES.map((n) => {
  const sx = n.x + n.w;
  const sy = n.y + n.h / 2;
  const ex = 1158;
  const ey = n.target;
  const c1x = sx + (ex - sx) * 0.47;
  const c2x = ex - 142;
  return { sx, sy, ex, ey, c1x, c2x, d: 'M ' + sx + ' ' + sy + ' C ' + c1x + ' ' + sy + ', ' + c2x + ' ' + ey + ', ' + ex + ' ' + ey };
});
const curvePoint = (r: typeof ROUTES[number], t: number) => {
  const u = 1 - t;
  return {
    x: u * u * u * r.sx + 3 * u * u * t * r.c1x + 3 * u * t * t * r.c2x + t * t * t * r.ex,
    y: u * u * u * r.sy + 3 * u * u * t * r.sy + 3 * u * t * t * r.ey + t * t * t * r.ey
  };
};
const ARC_TABLES = ROUTES.map((r) => {
  const points = Array.from({ length: 97 }, (_, i) => curvePoint(r, i / 96));
  const steps = points.map((p, i) => i === 0 ? 0 : Math.hypot(p.x - points[i - 1].x, p.y - points[i - 1].y));
  const lengths = steps.map((_, i) => steps.slice(0, i + 1).reduce((sum, value) => sum + value, 0));
  return { lengths, total: lengths[lengths.length - 1] };
});
const routePosition = (routeIndex: number, progress: number) => {
  const table = ARC_TABLES[routeIndex];
  const distance = progress * table.total;
  const found = table.lengths.findIndex((value) => value >= distance);
  const high = Math.max(1, found < 0 ? table.lengths.length - 1 : found);
  const low = high - 1;
  const fraction = (distance - table.lengths[low]) / Math.max(0.001, table.lengths[high] - table.lengths[low]);
  const t = (low + fraction) / 96;
  const p = curvePoint(ROUTES[routeIndex], t);
  const next = curvePoint(ROUTES[routeIndex], Math.min(1, t + 0.002));
  const prev = curvePoint(ROUTES[routeIndex], Math.max(0, t - 0.002));
  return { ...p, angle: Math.atan2(next.y - prev.y, next.x - prev.x) * 180 / Math.PI };
};

