  const finalFrame = Math.max(outroStart + 1, Math.min(610, durationInFrames - 1));
  const outro = ramp(frame, outroStart, finalFrame);
  const opening = ramp(frame, 0, end(440));
  let zoom = 1.2 - opening * 0.2;
