    const start = supplied?.startFrame ?? supplied?.spokenStartFrame ?? fallback.start;
    const end = supplied?.spokenEndFrame ?? supplied?.endFrame ?? fallback.end;
    return { ...fallback, start, end: Math.max(start + 1, end) };
  });
  const w = (index: number) => words[index - 462];
  const progress = (start: number, end: number, easing = ease) => interpolate(frame, [start, Math.max(start + 1, end)], [0, 1], { easing, extrapolateLeft: 'clamp', extrapolateRight: 'clamp' });
  const settleSpring = (start: number, end: number) => {
    const sample = (f: number) => spring({ frame: Math.max(0, f), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
    const value = sample(frame - start);
    const landing = progress(Math.max(start + 1, end - 12), end);
    return frame < start ? 0 : value * (1 - landing) + landing;
  };
  const structure = settleSpring(2, w(463).end);
  const inspection = progress(w(464).start, w(466).end);
  const travel = progress(w(468).start, w(468).end, Easing.bezier(0.2, 0.2, 0.32, 1));
  const release = progress(w(474).start, w(474).end);
  const after = progress(w(474).end, Math.max(w(474).end + 1, durationInFrames - 1), Easing.linear);
