  const start = (id: number) => cueFor(id)?.startFrame ?? fallbackStarts[id - 497];
  const end = (id: number) => cueFor(id)?.endFrame ?? fallbackEnds[id - 497];
  const progress = (a: number, b: number) => interpolate(frame, [a, Math.max(a + 1, b)], [0, 1], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp', easing: smooth });
