import React from "react";
import { AbsoluteFill, Sequence, useCurrentFrame, useVideoConfig, interpolate, spring, Easing, random } from "remotion";
import { mg } from "@frame60/mg";

type WordCue = { index?: number; wordIndex?: number; globalIndex?: number; id?: string | number; startFrame?: number; endFrame?: number; spokenStartFrame?: number; spokenEndFrame?: number; word?: string; text?: string };
type ShotProps = { wordCues?: WordCue[] };
type Pill = { id: string; x: number; y: number; w: number; slot: number; anchor: [number, number]; reveal: number; complete: number };

const C = { field: "#F3F1EB", paper: "#FFFFFF", ink: "#142536", slate: "#627383", teal: "#087F79", coral: "#ED705F", rule: "#D5DDD9" };
const FONT = '"Inter", Arial, sans-serif';
const TIGHT = '"Inter Tight", "Inter", Arial, sans-serif';
const MONO = '"IBM Plex Mono", monospace';
const FALLBACK: Record<number, [number, number]> = {
  513: [0, 4], 514: [0, 23], 515: [20, 31], 516: [29, 52],
  517: [57, 86], 518: [85, 115], 519: [121, 149], 520: [146, 192],
  521: [215, 236], 522: [233, 271], 523: [283, 324], 524: [322, 331],
  525: [330, 365], 526: [381, 439], 527: [456, 504], 528: [520, 538],
  529: [534, 570], 530: [570, 594], 531: [591, 632], 532: [629, 658]
};
const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const smooth = Easing.inOut(Easing.cubic);

export const GeneratedShot = (props: ShotProps) => {
  const frame = useCurrentFrame();
  const { fps, width, height, durationInFrames } = useVideoConfig();
  const cues = props.wordCues || [];
  const themeMode = "light" as const;

  const cue = (index: number): [number, number] => {
    const found = cues.find((c) => Number(String(c.wordIndex ?? c.globalIndex ?? c.index ?? c.id ?? "").replace(/^W/i, "")) === index)
      ?? (cues.length === 20 ? cues[index - 513] : undefined);
    const fallback = FALLBACK[index];
    return [found?.spokenStartFrame ?? found?.startFrame ?? fallback[0], found?.spokenEndFrame ?? found?.endFrame ?? fallback[1]];
  };
  const start = (index: number) => cue(index)[0];
  const end = (index: number) => cue(index)[1];
  const phrase = (s: number, e: number) => interpolate(frame, [s - 8, s + 6, e + 2, e + 22], [0, 1, 1, 0], clamp);

  const cameraFrames = [0, 3, end(516), start(517), start(519), start(521), start(523), end(525), start(526), start(527), start(529), start(530), start(531), end(532), Math.max(end(532) + 1, durationInFrames - 1)];
  const cam = (values: number[]) => interpolate(frame, cameraFrames, values, { ...clamp, easing: smooth });
  const zoom = cam([1, 1, 1, 1, 1.075, 1.12, 1.15, 1.15, 1.15, 1.15, 1.15, 1.15, 1.15, 1, 1]);
  const panX = cam([0, 0, 0, 0, -63, 47, 103, 103, 88, 0, -88, -88, -88, 0, 4]);
  const panY = cam([0, 0, 0, 0, 28, 44, 52, 52, -51, -54, -51, -51, -51, 0, 0]);
  const focusStart = start(531);
  const focusEnd = end(532);
  const focusReveal = interpolate(frame, [focusStart, focusEnd], [0, 1], { ...clamp, easing: smooth });
  const focusSpring = spring({ frame: Math.max(0, frame - focusStart), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
  const trackAccent = 1 - focusReveal * 0.7;

  const pills: Pill[] = [
    { id: "counting", x: 1404, y: 254, w: 370, slot: 3, anchor: [1460, 464], reveal: start(517), complete: end(518) },
    { id: "authentication", x: 992, y: 270, w: 398, slot: 2, anchor: [1140, 483], reveal: start(519), complete: end(520) },
    { id: "secrecy", x: 599, y: 254, w: 378, slot: 1, anchor: [790, 464], reveal: start(521), complete: end(522) },
    { id: "coercion", x: 146, y: 270, w: 438, slot: 0, anchor: [466, 482], reveal: start(523), complete: end(525) },
    { id: "accessibility", x: 182, y: 736, w: 448, slot: 4, anchor: [514, 640], reveal: start(526), complete: end(526) },
    { id: "auditability", x: 716, y: 754, w: 448, slot: 5, anchor: [958, 660], reveal: start(527), complete: end(527) },
    { id: "security", x: 1236, y: 736, w: 500, slot: 6, anchor: [1440, 642], reveal: start(529), complete: end(532) }
  ];

  const getLayout = (pill: Pill) => {
    const delay = 3 + pill.slot * 4;
    const raw = spring({ frame: Math.max(0, frame - delay), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
    const settle = interpolate(frame, [Math.max(delay + 1, end(516) - 10), end(516)], [0, 1], { ...clamp, easing: smooth });
    const progress = frame < delay ? 0 : raw * (1 - settle) + settle;
    const w = 82 + (pill.w - 82) * progress;
    const h = 66 + 84 * progress;
    const top = pill.y < 500;
    const centerX = pill.x + pill.w / 2;
    const centerY = pill.y + 75 + (top ? 32 : -32) * (1 - progress);
    return { x: centerX - w / 2, y: centerY - h / 2, w, h, ax: centerX + w / 2 - 37, ay: centerY, progress, top };
  };

  const Word = ({ index, children }: { index: number; children: React.ReactNode }) => {
    const f = frame - start(index);
    const a = interpolate(f, [0, 10], [0, 1], clamp);
    const rise = spring({ frame: Math.max(0, f), fps, config: { damping: 14, stiffness: 160, mass: 0.8 } });
    return <span style={{ display: "inline-block", opacity: f < 0 ? 0 : a, transform: `translateY(${(1 - rise) * 11}px)`, willChange: "transform, opacity" }}>{children}</span>;
  };

  const label = (id: string) => {
    switch (id) {
      case "counting": return <><Word index={517}>accurate</Word>{" "}<Word index={518}>counting</Word></>;
      case "authentication": return <><Word index={519}>voter</Word>{" "}<Word index={520}>authentication</Word></>;
      case "secrecy": return <><Word index={521}>ballot</Word>{" "}<Word index={522}>secrecy</Word></>;
      case "coercion": return <><Word index={523}>resistance</Word>{" "}<Word index={524}>to</Word>{" "}<Word index={525}>coercion</Word></>;
      case "accessibility": return <Word index={526}>accessibility</Word>;
      case "auditability": return <Word index={527}>auditability</Word>;
      default: return <><div><Word index={529}>security</Word>{" "}<Word index={530}>against</Word></div><div><Word index={531}>large-scale</Word>{" "}<Word index={532}>attacks</Word></div></>;
    }
  };

  const loomSize = { left: 80, top: 184, width: 1760, height: 860 };

  return (
    <AbsoluteFill style={{ overflow: "hidden", background: C.field, color: C.ink, fontFamily: FONT }}>
      <div style={{ position: "absolute", width: 1920, height: 1080, left: (width - 1920 * Math.min(width / 1920, height / 1080)) / 2, top: (height - 1080 * Math.min(width / 1920, height / 1080)) / 2, transform: `scale(${Math.min(width / 1920, height / 1080)})`, transformOrigin: "0 0", overflow: "hidden" }}>
        <AbsoluteFill style={{ background: "linear-gradient(155deg, #FBFAF7 0%, #F3F1EB 36%, #E7EBE7 70%, #F5F1E9 100%)" }} />
        <AbsoluteFill style={{ background: `radial-gradient(ellipse 64% 55% at ${51 + frame / 706 * 2}% 48%, rgba(255,255,255,0.96) 0%, rgba(255,253,245,0.52) 43%, rgba(226,236,229,0.08) 72%, transparent 100%)` }} />
        <AbsoluteFill style={{ opacity: 0.24 }}><mg.GridBackground mode={themeMode} gridSize={48} /></AbsoluteFill>
        <AbsoluteFill style={{ background: "radial-gradient(ellipse 96% 90% at 50% 40%, transparent 56%, rgba(74,82,72,0.06) 100%)" }} />

        <mg.CameraRig zoom={zoom} x={panX} y={panY}>
          <div style={{ position: "absolute", inset: 0, width: 1920, height: 1080 }}>
            <div style={{ position: "absolute", ...loomSize, borderRadius: 28, border: "1px solid rgba(142,157,153,0.40)", background: "linear-gradient(150deg, rgba(255,255,255,0.68) 0%, rgba(255,253,247,0.27) 53%, rgba(245,245,238,0.51) 100%)", boxShadow: "0 28px 68px -46px rgba(20,37,54,0.24), inset 0 1px 0 rgba(255,255,255,0.94)", overflow: "hidden" }}>
              <div style={{ position: "absolute", inset: 1, borderRadius: 27, background: "radial-gradient(ellipse 64% 46% at 50% 46%, rgba(255,255,255,0.90), transparent 82%)" }} />
            </div>

            <svg width={1920} height={1080} viewBox="0 0 1920 1080" style={{ position: "absolute", inset: 0, overflow: "visible" }}>
              <defs>
                <linearGradient id="s26-conduit" x1="0" y1="0" x2="1" y2="0">
                  <stop offset="0%" stopColor="#C4D0CA" stopOpacity="0.50" />
                  <stop offset="52%" stopColor="#AEBDB6" stopOpacity="0.85" />
                  <stop offset="100%" stopColor="#A0B2AD" stopOpacity="0.72" />
                </linearGradient>
                <filter id="s26-thread-soft" x="-10%" y="-50%" width="120%" height="200%"><feGaussianBlur stdDeviation="3" /></filter>
              </defs>

              <path d="M 173 565 H 432 M 452 453 V 431 H 483 M 1437 431 H 1468 V 453 M 452 663 V 685 H 483 M 1437 685 H 1468 V 663 M 1488 565 H 1747" fill="none" stroke={C.rule} strokeWidth={1.3} />
              <path d="M 432 485 V 545 M 432 585 V 638 M 1488 485 V 545 M 1488 585 V 638" fill="none" stroke={C.rule} strokeWidth={1} opacity={0.58} />

              {pills.map((pill) => {
                const L = getLayout(pill);
                const sx = pill.anchor[0];
                const sy = pill.anchor[1];
                const endpointY = L.ay + (L.top ? 20 : -20);
                const endpointX = L.ax - 22;
                const d = `M ${sx} ${sy} C ${sx} ${sy + (L.top ? -78 : 78)}, ${endpointX} ${endpointY + (L.top ? 104 : -104)}, ${endpointX} ${endpointY}`;
                return <g key={`thread-${pill.id}`}>
                  <path d={d} fill="none" stroke="#FFFFFF" strokeWidth={7} opacity={0.8} filter="url(#s26-thread-soft)" />
                  <path d={d} fill="none" stroke="url(#s26-conduit)" strokeWidth={1.5} />
                  <path d={`M ${sx - 8} ${sy} H ${sx + 8} M ${sx} ${sy - 5} V ${sy + 5}`} fill="none" stroke="#B4C1BB" strokeWidth={1.1} opacity={0.65} />
                </g>;
              })}
            </svg>

            <div style={{ position: "absolute", left: 604, top: 490, width: 712, height: 142, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", pointerEvents: "none" }}>
              <div style={{ fontFamily: TIGHT, fontSize: 42, fontWeight: 600, letterSpacing: "-1.25px", color: C.ink, lineHeight: 1.15 }}>A system</div>
              <div style={{ marginTop: 13, fontSize: 17, fontWeight: 500, color: C.slate, letterSpacing: "1.1px", display: "flex", alignItems: "center", gap: 14 }}>
                <span style={{ width: 31, height: 1, background: C.rule }} />
                <span>Illustrative system model.</span>
                <span style={{ width: 31, height: 1, background: C.rule }} />
              </div>
            </div>

            {pills.map((pill) => {
              const L = getLayout(pill);
              const active = phrase(pill.reveal, pill.complete) * trackAccent;
              const apertureX = L.w - 37;
              const apertureY = L.h / 2;
              const packetProgress = interpolate(frame, [pill.reveal, Math.max(pill.reveal + 12, pill.complete)], [0, 1], clamp);
              const packetOpacity = frame < pill.reveal ? 0 : interpolate(frame - pill.reveal, [0, 9], [0, 1], clamp);
              const packetTravel = Math.max(0, L.w - 116);
              return (
                <div key={pill.id} style={{ position: "absolute", left: L.x, top: L.y, width: L.w, height: L.h, borderRadius: 25, border: "1.5px solid #D5DDD9", boxSizing: "border-box", background: "linear-gradient(156deg, #FFFFFF 0%, #FFFEFA 60%, #F8F7F1 100%)", boxShadow: `0 16px 32px -24px rgba(20,37,54,0.27), 0 4px 11px -7px rgba(20,37,54,0.11), inset 0 1px 0 #FFFFFF`, overflow: "hidden" }}>
                  <div style={{ position: "absolute", inset: 0, opacity: active * 0.6, background: "linear-gradient(110deg, rgba(237,112,95,0.065), transparent 58%)" }} />
